/* agent run timeline */
.tl{position:relative;padding:0;overflow:visible!important}
.tl-head{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:14px 16px;border-bottom:1px solid var(--line)}
.tl-head .t{font-size:14px;font-weight:600}
.tl-sub{margin-top:2px;font-size:12.5px;color:var(--muted)}
.tl-body{position:relative;padding:8px 16px 4px}
.tl-axis{position:relative;height:22px;margin-left:170px;border-bottom:1px solid var(--line)}
.tl-axis span{position:absolute;top:2px;transform:translateX(-50%);font-family:var(--mono);font-size:10px;color:var(--muted)}
.tl-axis span::after{content:"";position:absolute;left:50%;top:16px;width:1px;height:5px;background:var(--line)}
.tl-row{display:grid;grid-template-columns:170px 1fr;align-items:center;height:36px}
.tl-name{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--text-dim);white-space:nowrap;overflow:hidden}
.tl-name .ms{color:var(--muted)}
.tl-row.live .tl-name{color:var(--text)}
.tl-lane{position:relative;height:100%;background-image:linear-gradient(90deg,var(--line) 1px,transparent 1px);background-size:calc(100% / 6) 100%}
.tl-bar{position:absolute;top:10px;height:16px;width:0;transition:width .12s linear;cursor:pointer}
.tl-bar.k-model,.tlk-model{background:#a993ff}
.tl-bar.k-tool,.tlk-tool{background:var(--accent)}
.tl-bar.k-retry,.tlk-retry{background:repeating-linear-gradient(135deg,var(--danger) 0 3px,rgba(255,90,95,.45) 3px 6px)}
.tl-bar:hover{filter:brightness(1.1)}
.tl-head-line{position:absolute;top:8px;bottom:4px;width:1px;background:var(--text);opacity:0;pointer-events:none;transition:opacity .2s}
.tl-head-line.on{opacity:.5}
.tl-legend{display:flex;gap:16px;padding:10px 16px 14px;font-size:12px;color:var(--text-dim)}
.tl-legend span{display:inline-flex;align-items:center;gap:6px}
.tl-legend i{width:12px;height:8px}
.tl-tip{position:absolute}

/* agent run timeline on small screens: name above the bar */
@media (max-width:700px){
  .tl-axis{margin-left:0}
  .tl-row{grid-template-columns:1fr;height:auto;padding:4px 0 2px}
  .tl-name{font-size:12px}
  .tl-lane{height:24px}
  .tl-bar{top:4px}
}

/* ---------- agent run timeline ---------- */
{
  const rowsEl = $('#tl-rows'), axis = $('#tl-axis'), play = $('#tl-play'), tip = $('#tl-tip'), tl = $('#tl');
  const T = 12;
  const steps = [
    ['stars','Plan the change','model',0,1.2,'1,240 tokens'],
    ['search','Search the docs','tool',1.2,3.0,'4 results'],
    ['description','Read Pricing.tsx','tool',3.0,3.8,'212 lines'],
    ['edit_note','Draft the edits','model',3.8,7.6,'3,880 tokens'],
    ['terminal','Run the tests','retry',7.6,8.6,'1 failure, retried'],
    ['terminal','Run the tests again','tool',8.6,10.2,'24 passed'],
    ['check_circle','Summarise','model',10.2,12,'640 tokens']
  ];
  axis.innerHTML = [0,2,4,6,8,10,12].map(s => `<span style="left:${s / T * 100}%">${s}s</span>`).join('');
  rowsEl.innerHTML = steps.map((s, i) => `<div class="tl-row" data-i="${i}"><span class="tl-name">${ic(s[0],'sm')}${s[1]}</span><span class="tl-lane"><span class="tl-bar k-${s[2]}" style="left:${s[3] / T * 100}%" data-i="${i}"></span></span></div>`).join('');
  const bars = $$('.tl-bar', rowsEl), rows = $$('.tl-row', rowsEl);
  let raf = 0;
  function run(){
    cancelAnimationFrame(raf); bars.forEach(b => b.style.width = '0'); rows.forEach(r => r.classList.remove('live'));
    setPill($('#tl-pill'), 'prog', 'Running'); play.classList.add('on');
    const t0 = performance.now(), speed = 1.6, lane = rowsEl.querySelector('.tl-lane');
    let lastI = -1;
    const tick = now => {
      const t = Math.min(T, (now - t0) / 1000 * speed);
      steps.forEach((s, i) => { const w = Math.max(0, Math.min(t, s[4]) - s[3]); bars[i].style.width = (w / T * 100) + '%'; rows[i].classList.toggle('live', t >= s[3] && t < s[4]); if (t >= s[3] && i > lastI){ lastI = i; ambient('c67', s[2] === 'retry' ? 'fail' : 'tick'); } });
      const lr = lane.getBoundingClientRect(), br = $('.tl-body', tl).getBoundingClientRect();
      play.style.left = (lr.left - br.left + t / T * lr.width) + 'px';
      $('#tl-sub').textContent = `${t.toFixed(1)}s elapsed, ${steps.filter(s => s[3] <= t).length} of ${steps.length} steps`;
      if (t < T) raf = requestAnimationFrame(tick);
      else { play.classList.remove('on'); rows.forEach(r => r.classList.remove('live')); setPill($('#tl-pill'), 'done', 'Completed'); $('#tl-sub').textContent = '12.0s total, 5,760 tokens, $0.042'; ambient('c67', 'done'); }
    };
    raf = requestAnimationFrame(tick);
  }
  bars.forEach(b => {
    b.addEventListener('mousemove', e => {
      const s = steps[+b.dataset.i], r = tl.getBoundingClientRect();
      tip.innerHTML = `<span class="mono-xs">${s[1]}</span>${(s[4] - s[3]).toFixed(1)}s, <b>${s[5]}</b>`;
      tip.style.left = Math.min(r.width - tip.offsetWidth - 8, e.clientX - r.left + 12) + 'px'; tip.style.top = (e.clientY - r.top + 14) + 'px'; tip.style.opacity = '1';
    });
    b.addEventListener('mouseleave', () => { tip.style.opacity = '0'; });
  });
  $('#tl-replay').addEventListener('click', () => { Sound.play('tab'); run(); });
  whenSeen($('#c67'), run);
}
